INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64377385', 64377385, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Penyusunan Matek dan Ranperkada RDTR Kecamatan Tawangmangu', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 1936880000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '1', 'Untuk mencapai berbagai tujuan dan target, terdapat enam (6) tahapan tugas yang perlu dilakukan oleh konsultan sesuai dengan Peraturan Menteri Agraria dan Tata Ruang/Kepala Badan Pertanahan Nasional (Permen ATR/Kepala BPN) Nomor 11 Tahun 2021 tentang Tata Cara Penyusunan, Peninjauan Kembali, Revisi, dan Persetujuan Substansi Rencana Tata Ruang Provinsi, Kabupaten/Kota, dan Rencana Detail Tata Ruang. Tahapan-tahapan ini saling terkait karena keluaran dari masing-masing tahapan menjadi masukan bagi tahapan berikutnya. Oleh karena itu, Penyedia Jasa Konsultansi diwajibkan untuk memahami alur kerja sesuai dengan peraturan perundang-undangan dan pedoman teknis yang berlaku terkait penyusunan materi teknis, rancangan peraturan kepala daerah (Ranperkada) RDTR, serta yang berkaitan dengan KLHS. Pelaksanaan Tahapan dan tugas sebagaimana dimaksud adalah sebagai berikut: ○ Tugas 1 : Persiapan ○ Tugas 2 : Pengumpulan data dan informasi ○ Tugas 3 : Pengolahan dan analisis data ○ Tugas 4 : Perumusan konsep perencanaan ○ Tugas 5 : Penyusunan Rancangan Peraturan Kepala Daerah RDTR Kabupaten/Kota ○ Tugas 6: Penyusunan Persyaratan untuk Persetujuan Substansi', 'Dalam melaksanakan tugasnya, konsultan akan didampingi oleh Supervisi dari Direktorat Jenderal Tata Ruang (DJTR) dan Pemerintah Daerah dalam perumusan penataan ruang. Pengawasan dari DJTR untuk memastikan bahwa seluruh tahapan tugas yang dilaksanakan oleh konsultan sesuai dengan peraturan dan pedoman teknis penyusunan RDTR, sementara Pemerintah Daerah untuk memastikan bahwa seluruh tugas konsultan sesuai dengan kebijakan daerah. Hal yang paling penting pada tahap awal adalah penetapan batas wilayah perencanaan antara tim konsultan dan pemerintah daerah. Selain itu, konsultan bersama pemerintah daerah perlu mengidentifikasi isu-isu strategis di Wilayah Perencanaan (WP). Kantor Pertanahan setempat juga turut mendampingi konsultan dalam tahapan pengumpulan data dan informasi, khususnya yang berkaitan dengan data administrasi pertanahan. Pada tahapan selanjutnya, konsultan didampingi oleh supervisi dari DJTR dan pemerintah daerah perlu menjalin komunikasi dengan masyarakat lokal, tokoh perempuan setempat, dan lainnya dalam pelaksanaan konsultasi publik untuk membahas perencanaan tata ruang. Peran pemerintah pusat, pemerintah daerah, dan masyarakat lokal dijelaskan lebih lanjut dalam Lampiran 1. Dalam setiap tahapan tugas tersebut, berbagai forum diskusi dan konsultasi publik harus diselenggarakan untuk memastikan bahwa proses studi dan perencanaan mengakomodasi aspirasi para pemangku kepentingan di daerah. Forum-forum ini merupakan bagian penting dalam membangun konsensus dan komitmen dari seluruh pemangku kepentingan terhadap implementasi RDTR di masa depan. Oleh karena itu, semua kesepakatan yang dicapai dalam forum-forum ini harus didokumentasikan dengan baik (dituangkan dalam Berita Acara).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1499986);
